+/** Chooses a supported Accept-Language preference, or the configured fallback. */
+export function requestLanguage(headers, fallback = "en") {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "accept-language")?.[1];
+  if (typeof header !== "string") return fallback;
+  let language = fallback;
+  let bestQuality = 0;
+  for (const preference of header.split(",")) {
+    const [range, ...parameters] = preference.trim().split(";");
+    const tag = range.trim().toLowerCase();
+    if (!/^(en|ko)(?:-[a-z0-9]{1,8})*$/.test(tag)) continue;
+    let quality = 1;
+    for (const parameter of parameters) {
+      const match = /^q\s*=\s*(.*)$/i.exec(parameter.trim());
+      if (match) quality = /^(?:0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/.test(match[1]) ? Number(match[1]) : 0;
+    }
+    if (quality > bestQuality) {
+      language = tag.split("-")[0];
+      bestQuality = quality;
+    }
+  }
+  return language;
+}
